with with_windows as (select *, rank() over (partition by channel order by shipping_fee nulls last) shipping_fee_rank, lag(discount, 2) over (partition by store_id order by amount, id) prev_discount, row_number() over (partition by status order by shipping_fee desc, id) row_seq from orders where status = 'COMPLETED') select id, customer_id, order_date, amount, discount, shipping_fee, shipping_fee_rank, prev_discount from with_windows
